Wrap(
  spacing: 16,
  runSpacing: 12,
  crossAxisAlignment: WrapCrossAlignment.center,
  children: [
    SgDiscardDigit(
      value: '$_page',
      controller: _pages,
      totalNumberPages: 8,
      stackDepth: 8,
    ),
    Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text('Página $_page de 8'),
        const SizedBox(height: 8),
        Wrap(
          spacing: 16,
          runSpacing: 12,
          crossAxisAlignment: WrapCrossAlignment.center,
          children: [
            SgButton(
              label: Text(context.tx('Anterior')),
              appearance: SgAppearance.outline,
              onClick: () => setState(() {
                _pages.decreasePage();
                _page = _pages.page();
              }),
            ),
            SgButton(
              label: Text(context.tx('Próxima')),
              onClick: () => setState(() {
                _pages.increasePage();
                _page = _pages.page();
              }),
            ),
          ],
        ),
      ],
    ),
  ],
)

SgDockLayout(
  id: 'showcase-dock-estado',
  defaultState: const SgDockLayoutState(
    toolbars: {
      'ferramentas': SgDockToolbarState(
        id: 'ferramentas',
        zone: SgDockZoneId.top,
        order: 0,
      ),
      'navegacao': SgDockToolbarState(
        id: 'navegacao',
        zone: SgDockZoneId.left,
        order: 0,
      ),
    },
  ),
  child: Builder(
    builder: (context) {
      final dock = SgDockLayout.maybeOf(context)!;
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          for (final tb in dock.state.toolbars.values)
            Text(
              '${tb.id}: zona ${tb.zone.value}, ordem ${dock.getToolbarOrder(tb.id)}',
            ),
          const SizedBox(height: 8),
          Wrap(
            spacing: 8,
            runSpacing: 8,
            children: [
              SgButton(
                label: Text(
                  context.tx('Mover "navegacao" para a direita'),
                ),
                size: SgSize.sm,
                onClick: () => dock.moveToolbar(
                  'navegacao',
                  SgDockZoneId.right,
                ),
              ),
              SgButton(
                label: Text(
                  context.tx('Mover "ferramentas" para a base'),
                ),
                size: SgSize.sm,
                appearance: SgAppearance.outline,
                onClick: () => dock.moveToolbar(
                  'ferramentas',
                  SgDockZoneId.bottom,
                ),
              ),
            ],
          ),
        ],
      );
    },
  ),
)

SizedBox(
  height: 190,
  child: SgDockLayout(
    id: 'showcase-dock-previa',
    child: Builder(
      builder: (context) {
        final dock = SgDockLayout.maybeOf(context)!;
        return Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                SgButton(
                  label: Text(context.tx('Simular arrasto')),
                  size: SgSize.sm,
                  onClick: () {
                    dock.setDropPreviewActive(true);
                    dock.setDraggingToolbarId('ferramentas');
                    dock.setDropIndicator(
                      const SgDockDropIndicator(
                        SgDockZoneId.top,
                        0,
                      ),
                    );
                  },
                ),
                SgButton(
                  label: Text(context.tx('Encerrar')),
                  size: SgSize.sm,
                  appearance: SgAppearance.outline,
                  onClick: () => dock.setDropPreviewActive(false),
                ),
              ],
            ),
            const SizedBox(height: 8),
            Row(
              children: [
                Expanded(
                  child: SgDockZone(
                    zone: SgDockZoneId.top,
                    child: Text(context.tx('Topo')),
                  ),
                ),
                Expanded(
                  child: SgDockZone(
                    zone: SgDockZoneId.free,
                    child: Text(context.tx('Livre')),
                  ),
                ),
              ],
            ),
          ],
        );
      },
    ),
  ),
)

