Builder(
  builder: (context) {
    var value = 0;
    return StatefulBuilder(
      builder: (context, set) => Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          SgFadeDigit(value: '$value'),
          const SizedBox(width: 24),
          FilledButton(
            onPressed: () => set(() => value = (value + 1) % 10),
            child: Text(context.tx('Próximo')),
          ),
        ],
      ),
    );
  },
)

Wrap(
  spacing: 16,
